#!/usr/bin/env python3
"""Render the local Agora publication draft from its compact, attributed summary.

Raw evidence is canonical in lab-evidence/sites/agora/20261015-optimized,
not in Labs. Verify FILES.json in that checkout before changing the summary.
No network, benchmark or deployment is performed by this renderer.
"""
from pathlib import Path
import json, html, argparse, re
R=Path(__file__).resolve().parents[1];D=R/'content/sites/agora';d=json.loads((D/'published.json').read_text())
args=argparse.ArgumentParser();args.add_argument('--release',action='store_true',help='Prepare release files after explicit approval; does not push/deploy');options=args.parse_args()
release=options.release or d.get('publication_state')=='released'
assert d['schema']==1
models=[('agora','Nift authored-source','authored'),('agora-agent','Nift maintained React ESM','rendered')]
cases=[('fresh','Fresh application state'),('warm-forced','Warm forced publication'),('unchanged','Unchanged'),('docs-edit','Document edit'),('shared-layout','Shared-layout edit')]
expected={'agora':[(199.82,1937.1),(43.77,750.4),(2.37,180.6),(7.51,1213.9),(49.63,979.6)],'agora-agent':[(71.79,1343.0),(45.09,748.4),(2.75,304.8),(7.24,1125.4),(52.22,916.7)]}
for m,_,_ in models:
 assert [(round(d['pipelines'][m][c]['seconds'],2),round(d['pipelines'][m][c]['tree_mib'],1)) for c,_ in cases]==expected[m]
assert [(round(x['seconds'],2),round(x['tree_mib'],1)) for x in d['baseline']]==[(592.09,4966.6),(607.14,5078.8)]
def esc(v):return html.escape(str(v),quote=True)
def link(url,label):return f'<a href="{esc(url)}">{esc(label)} ↗</a>'
def section(n,id,title,lead,body):return f'<section class="chapter" id="{id}" aria-labelledby="{id}-title"><div class="chapter-heading"><p class="eyebrow">{n} / {id.replace("-"," ")}</p><h2 id="{id}-title">{title}</h2><p class="intro">{lead}</p></div>{body}</section>'
def chart(title,caption,series,scale,key):
 unit='s' if key=='seconds' else 'MiB';places=2 if key=='seconds' else 1
 s=f'<figure class="chart"><figcaption><h3>{title}</h3><p>{caption}</p></figcaption><div class="axis" aria-hidden="true"><span>0</span><span>{scale/2:g}</span><span>{scale:g} {unit}</span></div>'
 for label,value,kind in series:
  assert 0<=value<=scale
  s+=f'<div class="chart-row {kind}"><div class="chart-label"><span>{label}</span><strong>{value:,.{places}f} {unit}</strong></div><div class="track" aria-hidden="true"><i style="width:{value/scale*100:.5f}%"></i></div></div>'
 return s+'</figure>'
def paired(cases_subset,scale_t,scale_m):
 out=''
 for c,title in cases_subset:
  out+=f'<div class="scenario"><h3>{title}</h3><div class="chart-pair">'
  for key,scale,title2 in [('seconds',scale_t,'Publication time'),('tree_mib',scale_m,'Sampled peak tree RSS')]:
   out+=chart(title2,'One observation per model · zero-origin linear scale',[(name,d['pipelines'][m][c][key],kind) for m,name,kind in models],scale,key)
  out+='</div></div>'
 return out
upbase='https://github.com/AgoraIO/docs-portal/tree/'+d['measured_commits']['upstream']
parts=['''<header class="mast"><a class="brand" href="@path('/')"><img src="@path('public/labs/identity/favicon-48.png')" alt="" width="30" height="30">NIFT <span>LABS</span></a><nav aria-label="Report navigation"><a href="#parity">Parity</a><a href="#architecture">Architecture</a><a href="#measurements">Measurements</a><a href="#maintenance">Judgement</a><a href="#evidence">Evidence</a></nav><a class="back" href="@path('sites/')">All experiments ↗</a></header>
<main id="main" class="wrap"><p class="review-banner"><strong>Publication review draft</strong> · Prepared locally. Not released or endorsed by Agora or TanStack.</p>
<section class="hero" aria-labelledby="report-title"><div><p class="eyebrow">Agora Docs / hybrid build architecture / October 2026</p><h1 id="report-title">Agora Docs<br><em>Nift +<br>TanStack Start</em></h1><p class="lede">2,003 generator-written documentation HTML pages, with TanStack Start and React retained alongside a more efficient Nift-powered build pipeline.</p><p>Agora’s public documentation portal combines a substantial bilingual content corpus with an interactive React application. This experiment asks whether Nift can improve the surrounding content and publication workflow while keeping the framework that delivers the experience.</p><p class="disclosure">Independent engineering experiment. Public source pinned before migration. Nift core unchanged. Complete pipeline measurements, with source-model and cache differences visible.</p></div><aside class="integration-map" aria-label="Build responsibilities"><p class="eyebrow">Retained responsibilities</p><div class="map-stage source"><span>01 / CONTENT</span><strong>Markdown / MDX<br>or maintained React ESM</strong><small>Two authoritative source models</small></div><div class="connector" aria-hidden="true">↓</div><div class="map-stage runtime"><span>02 / APPLICATION</span><strong>TanStack Start + React</strong><small>Routes · SSR · hydration · client navigation</small></div><div class="connector" aria-hidden="true">↓</div><div class="map-stage composition"><span>03 / PUBLICATION</span><strong>Nift</strong><small>Dependencies · raw HTML composition · output</small></div><p class="map-foot">Cooperation at the build boundary.<br>The application runtime remains.</p></aside></section>''']
parts.append(section('01','parity','The publication comes first.','Performance is useful only if the reconstructed application still does its job.',
'''<div class="proof-grid"><div><strong>2,017</strong><span>reference HTML paths</span></div><div><strong>1,657</strong><span>article identities</span></div><div><strong>3,100</strong><span>non-HTML, non-bundle reference paths</span></div><div><strong>1,049</strong><span>matching LLM content blocks</span></div></div>
<div class="columns"><div><h3>Corpus and independent clones</h3><p>The pinned upstream generator writes 2,003 documentation HTML files; aliases, fallbacks and verification files bring the complete reference HTML inventory to 2,017. Both independent GitHub clones preserve that inventory and every non-HTML, non-bundle reference path. Authored publication contains 6,859 files; the maintained-React model contains 6,862. Content-addressed bundles differ from upstream by design.</p><p>All 1,657 compiled article modules match between the models. Canonical document payload fields, Markdown download bytes, search entry content and LLM blocks reconcile with the frozen reference. Search-row and LLM-block ordering varies in upstream and is compared separately.</p></div><div><h3>Actual application behavior</h3><p>Representative browser checks exercise React hydration, search and client navigation/history, API controls, code tabs, FAQ filtering, themes and the mobile drawer. Chinese Start hydration, localized Orama search and client navigation pass at an explicitly local fixture origin.</p><p>These are representative behavioral and visual checks, not a claim that every route and viewport is pixel-identical. A saved dark theme triggers a React hydration mismatch in the frozen upstream output and the migration; the application recovers. The unchanged theme/root implementation and matched browser reproduction establish this as an inherited defect, not clean hydration across every theme state. Complete Chinese production publication and actual provider behavior remain separate certification gaps.</p></div></div>
<div class="note"><strong>Restoration is checked, not assumed.</strong><p>Warm and restored outputs retain exact non-HTML bytes. HTML agrees after comparison-only normalization of the Router’s bootstrap <code>updatedAt</code> fields inside its stream-barrier script. Article content and other dates are untouched; production HTML is never normalized. A real upstream highlighting variation is retained in the repeatability evidence.</p></div>'''))
parts.append(section('02','architecture','A different build workflow. The same framework.','The original portal uses TanStack Start/Router, React, Vite and Fumadocs. Nift takes responsibility for publication composition rather than replacing their runtime.',
'''<p>The project was selected to test a hybrid adoption path: substantial authored MDX, shared components, bilingual navigation, platform variants, OpenAPI references, search and machine-readable exports. Replacing all of this with a static approximation would answer a different question.</p>
<div class="columns models"><article><p class="eyebrow">Nift agora / authored-source</p><h3>Keep authored content authoritative.</h3><ol class="pipeline"><li>Maintained Markdown / MDX, frontmatter, includes, navigation and OpenAPI</li><li>Independent Fumadocs compilation → cached React ESM + metadata</li><li>Derived search, Markdown and LLM projections</li><li>Retained Vite / TanStack application + production route SSR</li><li>Transient HTML → Nift raw composition → publication</li></ol><p>Generated modules and HTML are disposable. Recursive includes, image bytes/dimensions, compiler configuration, source hashes and package revisions participate in invalidation. Editorial dates retain their upstream seed and explicit maintenance workflow.</p></article><article><p class="eyebrow">Nift agora-agent / maintained React ESM</p><h3>Maintain the compiled representation.</h3><ol class="pipeline"><li>Maintained React ESM articles + explicit catalog/raw/processed metadata</li><li>Derived search, Markdown and LLM projections</li><li>Retained Vite / TanStack application + production route SSR</li><li>Transient HTML → Nift raw composition → publication</li></ol><p>No Markdown/MDX article compiler runs during routine publication. The maintained source is React ESM, not HTML-only: shared interactive components still run. Agents must coordinate article modules and their text/metadata representations when editing content.</p></article></div>
<div class="note"><p>Fumadocs still supplies content semantics and UI. TanStack still supplies routing and SSR, Vite still bundles the application, and React still renders and hydrates it. These measurements cover the orchestrated pipeline, <strong>not native Nift <code>&#64;markup</code> throughput</strong>.</p></div>'''))
parts.append(section('03','measurements','Complete work, measured explicitly.','Two upstream observations and one observation per Nift scenario. These are engineering observations, not statistically established distributions.',
'<div class="chart-pair">'+''.join(chart(title,'Upstream production runs and Nift fresh-state runs have different cache/source conditions.',[(f'Upstream production · observation {i+1}',x[key],'upstream') for i,x in enumerate(d['baseline'])]+[(name,d['pipelines'][m]['fresh'][key],kind) for m,name,kind in models],scale,key) for title,key,scale in [('Production / fresh-state elapsed time','seconds',650),('Production / fresh-state sampled tree RSS','tree_mib',5500)])+'</div>'+'''
<div class="table-scroll" tabindex="0" role="region" aria-label="Upstream production observations"><table><caption>Accepted upstream production observations · cache conditions are not matched to Nift fresh state</caption><thead><tr><th scope="col">Observation</th><th scope="col">Wall time</th><th scope="col">Sampled peak tree RSS</th></tr></thead><tbody>'''+''.join(f'<tr><th scope="row">Upstream {i+1}</th><td>{x["seconds"]:.2f}s</td><td>{x["tree_mib"]:,.1f} MiB</td></tr>' for i,x in enumerate(d['baseline']))+'''</tbody></table></div>
<p>The two upstream observations are 592.09s / 4,966.6 MiB and 607.14s / 5,078.8 MiB. Their midpoint gives descriptive ratios of approximately 3.0× authored and 8.4× maintained-React elapsed improvement, with about 61% and 73% lower sampled RSS. The midpoint is neither a median campaign nor a cache-matched benchmark. Source representations perform different work.</p>
<div class="table-scroll" tabindex="0" role="region" aria-label="Nift complete pipeline results"><table><caption>Complete Nift pipeline · one observation per row/model · wall time / sampled peak tree RSS</caption><thead><tr><th scope="col">Workload</th><th scope="col">Nift agora<br>authored-source</th><th scope="col">Nift agora-agent<br>maintained React ESM</th></tr></thead><tbody>'''+''.join('<tr><th scope="row">'+label+'</th>'+''.join(f'<td><strong>{d["pipelines"][m][c]["seconds"]:.2f}s</strong><small>{d["pipelines"][m][c]["tree_mib"]:,.1f} MiB</small></td>' for m,_,_ in models)+'</tr>' for c,label in cases)+'''</tbody></table></div>
<div class="note"><strong>The warm workload is not the upstream workload.</strong><p>Fresh Nift state retains installed dependencies but regenerates application/content artifacts from maintained sources. Forced full publication reuses valid compiled artifacts while rendering/composing every page. Upstream production observations reused build/install state and follow the original complete production command. Clone/install time, source editing and browser inspection are excluded; OS caches are uncontrolled.</p></div>'''))
parts.append(section('04','iteration','A smaller edit should trigger smaller work.','Unchanged, document-edit and shared-layout workloads are production publications, not development-server or HMR measurements.',
paired(cases[2:],60,1400)+'''<div class="note"><strong>Incremental memory belongs beside incremental time.</strong><p>Both models avoid application bundling for the measured prose-only document edit. They still update the necessary content/projections and render affected routes. The edit leaves editorial dates unchanged; metadata/date changes may invalidate more work. Shared CSS/layout changes rebuild the application and fan out through publication.</p><p>The authored and maintained-React edits are deliberately different source operations. Manual coordination of agent text and module edits is outside the clock. These results do not establish total editing productivity.</p></div>'''))
parts.append(section('05','optimization','Remove repeated work before tuning Nift.','The improvement came from the combined architecture and its preparation stages.',
'''<div class="columns"><div><h3>Separate compilation and publication</h3><p>Article compilation no longer depends on rebundling the entire application. Valid React ESM and metadata survive ordinary publications. Clean payload paths defer expensive worker/source imports; cached projections are reused when their inputs are unchanged.</p><h3>Bound work and memory</h3><p>Compiler workers keep bounded lifetimes and merge metadata deltas once. SSR uses two production workers with bounded route batches and heaps. An immutable shared route plan avoids repeated corpus-wide dependency planning in each batch.</p></div><div><h3>Load only the metadata needed</h3><p>Compact frontmatter heads and lazy per-document records replace eagerly retaining the full projection catalog in every SSR worker. The complete catalog still exists for exports. Server-only metadata stays out of the public tree.</p><h3>Preserve correctness while caching</h3><p>Asset copying checks both source and destination identity and repairs missing/corrupt outputs. Raw source hashes track edits that do not change compiled React. Retirement and restoration gates accompany incremental shortcuts.</p></div></div>
<div class="progress"><div><span>Authored warm full</span><strong>87.21s → 43.77s</strong></div><div><span>Maintained React warm full</span><strong>92.28s → 45.09s</strong></div></div>
<p>The initial corrected and optimized captures remain separate historical checkpoints. The earlier SSR path selected development React; the optimized path explicitly uses production React. This is an implementation improvement, not equivalent renderer conditions hidden behind a single table. Initial incomplete-scope captures and a rejected agent projection integration are retained locally as rejected diagnostics.</p>'''))
phase_rows=''
for m,name,_ in models:
 phases=d['pipelines'][m]['fresh']['phases']; phase_rows+=f'<tr><th scope="row">{name}</th>'
 for key in ['content','maintained-content','payloads','application','render','composition']:
  found=next((x for x in phases if x.get('phase')==key),None)
  val=found.get('seconds',found.get('wallSeconds')) if found else None
  phase_rows+=f'<td>{val:.2f}s</td>' if isinstance(val,(float,int)) else '<td>—</td>'
 phase_rows+='</tr>'
parts.append(section('06','remaining-costs','The remaining costs stay visible.','Neither model reached the sub-10-second aspiration; warm forced publication also remains above the 20-second milestone.',
'''<div class="table-scroll" tabindex="0" role="region" aria-label="Fresh pipeline phase costs"><table class="wide"><caption>Isolated fresh pipeline phases · same captured observations · omitted asset/registration/OpenAPI/orchestration costs remain in whole-pipeline totals</caption><thead><tr><th scope="col">Model</th><th>MDX compilation</th><th>Maintained content</th><th>Projections</th><th>Application</th><th>Route SSR</th><th>Nift composition</th></tr></thead><tbody>'''+phase_rows+'''</tbody></table></div>
<p>Fresh authored compilation took 132.85s; full projection work costs about 18s in both models. Production route SSR still costs around 41–42s, while Nift composition takes about 0.56s in these fresh observations. Warm forced publication is dominated by SSR; fresh and document-edit memory peaks occur in content/projection preparation. The maintained-React pipeline still pays meaningful costs despite avoiding MDX compilation.</p><p>Fixed fingerprint/planning/startup work keeps no-op publication above two seconds. Large shared changes still fan out. These are future integration/compiler/SSR profiling targets; no deeper performance project is required to explain the current result honestly.</p>'''))
parts.append(section('07','certification','A certified global corpus. A qualified deployment story.','The evidence supports the migration result, with clear boundaries on production claims.',
'''<div class="certification-grid"><article><span class="status pass">PASS / GLOBAL</span><h3>Content and application checks</h3><p>Independent clones, complete reference paths, projections, module reconciliation and restoration pass. Type checks and 101 focused tests per model passed. Representative English hydration/navigation and Chinese fixture behavior passed.</p></article><article><span class="status qualified">QUALIFIED / TESTS</span><h3>Inherited full suite</h3><p>The historical 46 failure entries were independently classified: 43 reproduce upstream in the named baseline checks; three migration/test failures have subsequent focused passing evidence. Missing CLI dependency and DOM-environment assumptions are identified separately. The full inherited suite is not declared green.</p></article><article><span class="status qualified">QUALIFIED / HOSTING</span><h3>Equivalent rules, local proof</h3><p>All 393 redirects, 65 conditional routes and the 1,000 bulk redirects match pinned upstream. Twenty local HTTP cases cover redirects, deep links, assets, Markdown negotiation, machine-readable routes and 404s. This is a subset emulator, not a deployed provider acceptance test.</p></article><article><span class="status open">OPEN / PRODUCTION</span><h3>Regional and provider certification</h3><p>No authoritative new Chinese origin was found; current public Shengwang links still use the legacy origin. Complete regional deployment, provider rule precedence, Accept-negotiated caching and build-image integration remain unverified. The build image must supply Nift explicitly.</p></article></div>
<p>The pinned hosting configuration has no explicit cache-header policy, so provider/dashboard defaults cannot be reconstructed from source alone. Four read-only current upstream requests returned correct deep-link HTML, Accept-negotiated Markdown, a Markdown download and a 404; observed responses used <code>public, max-age=0, must-revalidate</code>. This establishes current upstream behavior, not the Nift deployment’s cache correctness. Private Algolia indexing, external-service writes and production API workflows were not exercised. Local Orama fallback was tested. Original CDN assets remain external; this is not a complete offline mirror.</p>
<div class="note"><strong>Latest correctness fix is included in reviewed source.</strong><p>A frontmatter comment can change raw search text without changing the compiled article URL. The authored updater now tracks maintained-source hashes separately. A real YAML-comment test proves correct search updates and exact fixture restoration. This fix follows the captured performance checkpoint and receives no unmeasured speed claim.</p></div>'''))
parts.append(section('08','maintenance','Preferred: Nift agora, authored-source.','For agent-led maintenance under human direction, human editing and mixed workflows.',
'''<div class="recommendation"><p class="eyebrow">Three-way maintenance judgement</p><h3>One authoritative source wins this tradeoff.</h3><p><strong>Upstream TanStack/Fumadocs</strong> remains the incumbent integrated application. <strong>Nift agora</strong> preserves Markdown/MDX, frontmatter, includes and structured references as authoritative inputs while deriving search, downloads, metadata and LLM exports. <strong>Nift agora-agent</strong> saves fresh compilation time by maintaining React ESM and coordinated text/metadata records directly.</p><p>The agent-primary model has the fastest observed fresh build, but similar warm-publication and document-edit costs. Its extra source coordination does not outweigh the authored model’s reviewability and single source of truth. Removing migration effort and incumbency does not change this preference.</p></div>
<p>The engineering recommendation is a serious evaluation of <strong>Nift alongside TanStack Start</strong> for Agora’s documentation build workflow. It is not a recommendation to abandon TanStack or an unconditional production migration decree. The local global result is reproducible; deployment, service boundaries and regional production certification still need owner review.</p>'''))
parts.append(section('09','methodology','Read the boundaries with the numbers.','Source revisions, workloads and memory scopes are part of the result.',
'''<dl class="method-list"><div><dt>Fresh application state</dt><dd>Installed dependencies retained; no generated application/content artifacts. Authored compiles all 1,657 articles. The agent model’s maintained React modules are source, not an unreported generated cache.</dd></div><div><dt>Warm forced publication</dt><dd>Valid application/content/projections retained. All required pages are rendered and Nift-composed again; this is not a no-op or fresh-source benchmark.</dd></div><div><dt>Process-tree RSS</dt><dd>Same observer sums simultaneously sampled workload-process-group and descendant RSS, excluding the observer/GNU-time wrapper. Shared pages can be counted more than once and short peaks missed. Requested sleep is 20ms; actual intervals are longer. RSS is not peak physical memory or unique-set size.</dd></div><div><dt>Individual process RSS</dt><dd>GNU time maximum individual-process RSS is retained separately in canonical samples. It is not interchangeable with the tree-RSS graphs shown here.</dd></div><div><dt>Machine and toolchain</dt><dd>Recorded environment: Linux 7.0.0-29 x86_64/glibc 2.43, Node 22.22.1, Bun 1.4.3 and Nift 4.12.0. CPU/RAM were not recorded with the benchmark. A later review-time snapshot reports an Intel i7-12700H, 20 logical CPUs and about 61 GiB RAM; it cannot establish historical load or available memory.</dd></div><div><dt>Sampling and provenance</dt><dd>Two accepted upstream production observations; one Nift observation per model/scenario. No additional upstream or repeated final benchmark campaign. Source representation, cache conditions and production-runtime corrections differ; no statistical dominance or universal latency claim.</dd></div></dl>'''))
evidence_info=d.get('evidence',{})
sha=evidence_info.get('commit','PENDING');path='sites/agora/20261015-optimized'
evidence_url=f'https://github.com/nift-experiments/lab-evidence/tree/{sha}/{path}'
# Evidence commit is local until user release authorization; proposed links are explicit.
evidence_body='<p class="pending">Canonical evidence is prepared locally in <code>nift-experiments/lab-evidence/'+path+'</code>. It has not been published. The proposed pinned evidence link will become available only after release approval.</p>'
if sha!='PENDING':evidence_body+=f'<p>{link(evidence_url,"Proposed canonical evidence — pending public release")} · local commit <code>{sha[:12]}</code></p>'
evidence_body+='<div class="columns"><div><h3>Measured implementations</h3><ul>'
for m,_,_ in models:evidence_body+='<li>'+link('https://github.com/nift-experiments/'+m+'/tree/'+d['measured_commits'][m],m+' · measured '+d['measured_commits'][m][:7])+'</li>'
evidence_body+='<li>'+link(upbase,'Upstream AgoraIO/docs-portal · pinned source')+'</li></ul></div><div><h3>Reviewed final implementations</h3><ul>'
for m,_,_ in models:evidence_body+='<li>'+link('https://github.com/nift-experiments/'+m+'/tree/'+d['reviewed_commits'][m],m+' · reviewed '+d['reviewed_commits'][m][:7])+'</li>'
evidence_body+='</ul><p>The authored revision adds the raw-source correctness fix after measurement. The agent revision adds closeout documentation. Neither later revision is presented as the captured timing source.</p></div></div>'
evidence_body+='''<p>Canonical evidence includes commands, exact samples and RSS traces, source/toolchain manifest, output hashes, parity/restoration receipts, classified unit failures, Chinese and hosting qualifications, and independent architecture/correctness/methodology reviews. Evidence lives outside Labs; the website keeps only its compact displayed summary.</p><p>Readers can reproduce the project with <code>bun run install:app</code>, <code>bun run build</code> and <code>bun run build:full</code>, with the pinned Node/Bun/Nift toolchain installed. Cloning and dependency installation are outside the measured pipeline.</p>'''
parts.append(section('10','evidence','Exact revisions. Retained observations.','The release package is prepared for review; publication requires explicit approval.',evidence_body))
parts.append('''<footer class="report-footer"><span>Agora Docs / Nift + TanStack Start</span><a href="@path('sites/')">Explore the migration series →</a><span>Independent report · publication draft</span></footer></main>''')
body='\n'.join(parts)+'\n'
if release:
 body=re.sub(r'<p class="review-banner">.*?</p>','',body)
 body=body.replace('Independent report · publication draft','Independent report · October 2026')
 body=re.sub(r'<p class="pending">.*?</p>','<p>Canonical evidence is pinned by exact commit and SHA-256 file inventory.</p>',body)
 body=body.replace('Proposed canonical evidence — pending public release','Canonical evidence').replace(' · local commit ',' · evidence commit ')
 body=body.replace('The release package is prepared for review; publication requires explicit approval.','Source, raw observations, checks and limitations remain available for inspection.')
 d['publication_state']='released';d['evidence']['status']='published';(D/'published.json').write_text(json.dumps(d,indent=2)+'\n')
 head=R/'templates/sites/agora/head.html';head.write_text(head.read_text().replace('<meta name="robots" content="noindex,nofollow">\n',''))
 catalogue=R/'content/data/sites.json';entries=json.loads(catalogue.read_text())
 for entry in entries:
  if entry['slug']=='agora':entry['status']='Results published'
 catalogue.write_text(json.dumps(entries,indent=2,ensure_ascii=False)+'\n')
(D/'index.html').write_text(body)
print('Rendered Agora report from compact attributed summary; no deployment')
